-- ============================================
-- 早期鸟类物种导入数据
-- 说明：其中 /birds/*.jpg 仍是占位路径，入库时统一置空，
-- 由前端占位封面负责兜底，后续有真实图片资源后再单独补充。
-- ============================================

WITH source AS (
  SELECT *
  FROM jsonb_to_recordset($json$[{"slug":"tachybaptus-ruficollis","common_name":"小䴙䴘","scientific_name":"Tachybaptus ruficollis","aliases":["水葫芦","王八鸭子"],"taxon_group":"䴙䴘科 小䴙䴘属","identification_notes":"小型游禽，全长23~28厘米。雌雄相似。整体近球状，在水上游泳常被人误认为鸭子，实际比鸭子小得多，且嘴尖。繁殖期头颈黑褐色、脸侧及颈侧棕红色，嘴角黄色，眼睛虹膜黄色。非繁殖期颜色浅得多，头颈部的棕红色区域变为浅棕色。雏鸟身上有黑色条纹，头颈部的尤为突出。","habitat_notes":"几乎在有水的环境都有分布。","seasonality_notes":"全年可见，可能几种居留型都存在，极常见。","cover_image_url":"/birds/tachybaptus-ruficollis.jpg","is_active":true},{"slug":"podiceps-cristatus","common_name":"凤头䴙䴘","scientific_name":"Podiceps cristatus","aliases":["浪里白"],"taxon_group":"䴙䴘科 䴙䴘属","identification_notes":"中型游禽，全长51~58厘米。雌雄相似，繁殖期头部有明显的深色羽冠，脸侧有“棕红———黑”配色的大围领。非繁殖期头饰褪去，头顶黑色，身体羽色也变淡，颈部、胁部都为白色，游泳吃水较深，远看时白色的长脖子非常明显。","habitat_notes":"栖息在相对比较大的湿地生境。","seasonality_notes":"夏候鸟、旅鸟，3月至11月可见，也有极少数个体在此越冬。","cover_image_url":"/birds/podiceps-cristatus.jpg","is_active":true},{"slug":"phalacrocorax-carbo","common_name":"普通鸬鹚","scientific_name":"Phalacrocorax carbo","aliases":["鱼鹰"],"taxon_group":"鸬鹚科 鸬鹚属","identification_notes":"中型游禽，全长70~90厘米。雌雄相似。通体黑色、闪蓝绿色光泽，成鸟繁殖期脸侧有白色丝状羽，下胁具白斑。幼鸟体羽偏褐色。","habitat_notes":"在近郊和远郊的水库湿地比较常见。","seasonality_notes":"每年春秋两季(3月至5月，9月至11月)，迁经北京。","cover_image_url":"/birds/phalacrocorax-carbo.jpg","is_active":true},{"slug":"ardea-cinerea","common_name":"苍鹭","scientific_name":"Ardea cinerea","aliases":["长脖老等","灰鹤"],"taxon_group":"鹭科 鹭属","identification_notes":"大型鹭类，全长90~100厘米。周身苍灰色，下体颜色较淡，大长嘴黄色很醒目，头后有两根黑色“小辫”，颈前缀有黑色纵纹。幼鸟羽色较成鸟深，头后小辫不显著。","habitat_notes":"在近郊和远郊湿地比较常见，冬季有少量留居市区或近郊的不冻水域附近。","seasonality_notes":"每年3月至11月都能见到。","cover_image_url":"/birds/ardea-cinerea.jpg","is_active":true},{"slug":"ardea-alba","common_name":"大白鹭","scientific_name":"Ardea alba","aliases":["白老等"],"taxon_group":"鹭科 鹭属","identification_notes":"大型鹭类，全长82~100厘米。雌雄相似。通体白色，嘴裂伸至眼后。繁殖期嘴黑、眼先绿色，颈下和背部有长的蓑羽。非繁殖期嘴和眼先变黄，身上蓑羽消失。","habitat_notes":"适应了新环境，在一些公园湿地能经常见到。","seasonality_notes":"主要为夏候鸟和旅鸟，少量个体在此越冬。","cover_image_url":"/birds/ardea-alba.jpg","is_active":true},{"slug":"egretta-garzetta","common_name":"白鹭","scientific_name":"Egretta garzetta","aliases":["小白鹭"],"taxon_group":"鹭科 白鹭属","identification_notes":"中型涉禽，全长52~68厘米。雌雄相似。通体白色。繁殖期头后有两根细长的白辫，下颈及背部有许多长的蓑羽。非繁殖期无白辫和蓑羽。跗跖黑色、脚趾黄色。","habitat_notes":"一些湿地公园、水库，冬季在动物园水禽湖等。","seasonality_notes":"夏候鸟、旅鸟，冬季有零星个体留居北京。","cover_image_url":"/birds/egretta-garzetta.jpg","is_active":true},{"slug":"ardeola-bacchus","common_name":"池鹭","scientific_name":"Ardeola bacchus","aliases":[],"taxon_group":"鹭科 池鹭属","identification_notes":"中型涉禽，全长38~54厘米。繁殖期头颈棕色、背蓝灰，余部白色。非繁殖期头颈淡黄褐色、具棕色纵纹，背棕灰。","habitat_notes":"喜欢植被丰富的水域，受自身体形和行为特点所限，基本不出现在深水区域。","seasonality_notes":"夏候鸟、旅鸟，4月中旬至10月初可见。","cover_image_url":"/birds/ardeola-bacchus.jpg","is_active":true},{"slug":"nycticorax-nycticorax","common_name":"夜鹭","scientific_name":"Nycticorax nycticorax","aliases":["夜洼子","星洼子"],"taxon_group":"鹭科 夜鹭属","identification_notes":"中型鹭类，全长48~58厘米。成鸟头顶至背部蓝灰色，头后有2条很长的白色“小辫”，下体灰白色，虹膜红色。幼鸟周身暗褐色，满布浅棕色、白色斑点。","habitat_notes":"北京各处的湿地都能见到，冬季有少量留居市区和近郊的不冻水域附近。","seasonality_notes":"每年3月至10月可见，夏季尤其易见。","cover_image_url":"/birds/nycticorax-nycticorax.jpg","is_active":true},{"slug":"ixobrychus-sinensis","common_name":"黄斑苇鳽","scientific_name":"Ixobrychus sinensis","aliases":["小水骆驼"],"taxon_group":"鹭科 苇鳽属","identification_notes":"小型涉禽，全长30~38厘米。雄鸟身体除飞羽、尾为黑色外，大部分为浅黄褐色、微泛红，头顶铅灰色。雌鸟羽色较雄鸟灰暗，且多褐色纵纹。","habitat_notes":"几乎只要有芦苇、香蒲、荷花的地方就能见到。","seasonality_notes":"夏候鸟、旅鸟，5月至10月初可见。","cover_image_url":"/birds/ixobrychus-sinensis.jpg","is_active":true},{"slug":"botaurus-stellaris","common_name":"大麻鳽","scientific_name":"Botaurus stellaris","aliases":["大水骆驼"],"taxon_group":"鹭科 麻鳽属","identification_notes":"大型游禽，全长65~78厘米。周身羽毛枯黄色，满布棕黄色、深褐色、黑色的斑点和条纹。保护色隐蔽性很好。","habitat_notes":"夏季有繁殖种群在郊区大型湿地，冬季在市区和近郊公园湿地的芦苇丛中更容易见到。","seasonality_notes":"北京市区、郊区的湿地中全年可见。","cover_image_url":"/birds/botaurus-stellaris.jpg","is_active":true},{"slug":"ciconia-nigra","common_name":"黑鹳","scientific_name":"Ciconia nigra","aliases":["乌鹳","锅鹳"],"taxon_group":"鹳科 鹳属","identification_notes":"大型涉禽，全长100~110厘米。成鸟雌雄相似。上体黑色，有闪绿、紫色金属光泽；下体白色；嘴红色、长而粗壮；眼周裸皮及足红色。幼鸟整体偏褐色。","habitat_notes":"生活在山区河流环境，于周围峭壁上营巢繁殖。","seasonality_notes":"留鸟、旅鸟。","cover_image_url":"/birds/ciconia-nigra.jpg","is_active":true},{"slug":"cygnus-cygnus","common_name":"大天鹅","scientific_name":"Cygnus cygnus","aliases":["天鹅","鹄"],"taxon_group":"鸭科 天鹅属","identification_notes":"大型游禽，全长120~160厘米。雌雄相似。成鸟通体白色；嘴端黑色，嘴基黄色、向前延伸至鼻孔下；足黑色。幼鸟体羽多灰色。","habitat_notes":"喜欢栖息于大型开阔水域，通常不会降落到市区公园的小湖面上。","seasonality_notes":"主要为旅鸟，也有少量越冬群体，10月至次年4月初可见。","cover_image_url":"/birds/cygnus-cygnus.jpg","is_active":true},{"slug":"cygnus-columbianus","common_name":"小天鹅","scientific_name":"Cygnus columbianus","aliases":["天鹅","短嘴天鹅"],"taxon_group":"鸭科 天鹅属","identification_notes":"大型游禽，全长110~130厘米。体形比大天鹅小一些，脖子相对显得没那么细长。嘴上的黑色通常都会延伸盖过鼻孔。","habitat_notes":"栖居环境、习性和大天鹅相同，有时也会混群活动。市区一些有较大湖面的公园停歇。","seasonality_notes":"旅鸟、冬候鸟，10月中旬至次年4月初可见。","cover_image_url":"/birds/cygnus-columbianus.jpg","is_active":true},{"slug":"anser-cygnoides","common_name":"鸿雁","scientific_name":"Anser cygnoides","aliases":["大雁"],"taxon_group":"鸭科 雁属","identification_notes":"大型游禽，全长82~96厘米。雌雄相似。嘴黑，头顶至后颈具棕色条带。","habitat_notes":"主要栖息于郊区的大型湿地。","seasonality_notes":"旅鸟，迁徙季节可见。","cover_image_url":"/birds/anser-cygnoides.jpg","is_active":true},{"slug":"anser-anser","common_name":"灰雁","scientific_name":"Anser anser","aliases":["大雁","红嘴雁"],"taxon_group":"鸭科 雁属","identification_notes":"大型游禽，全长76~88厘米。雌雄相似。嘴、脚粉色。翼上覆羽浅灰色，飞行时显得翅膀前半部近白色。","habitat_notes":"郊区各大水库湿地，市区一些园林的大型水域也偶能见到。","seasonality_notes":"旅鸟。春秋迁徙季节多见。","cover_image_url":"/birds/anser-anser.jpg","is_active":true},{"slug":"tadorna-ferruginea","common_name":"赤麻鸭","scientific_name":"Tadorna ferruginea","aliases":["黄鸭"],"taxon_group":"鸭科 麻鸭属","identification_notes":"中型游禽，全长58~68厘米。全身大部为橙黄色，头偏白，翅尖黑色，嘴、足黑色。雄鸟繁殖期颈部有一个黑环。","habitat_notes":"多在迁徙季节和冬季见于郊区的湿地、农田，市区公园大水面上有时也会飞来。","seasonality_notes":"主要为旅鸟、冬候鸟，10月至次年4月可见。","cover_image_url":"/birds/tadorna-ferruginea.jpg","is_active":true},{"slug":"aix-galericulata","common_name":"鸳鸯","scientific_name":"Aix galericulata","aliases":["官鸭"],"taxon_group":"鸭科 鸳鸯属","identification_notes":"小型游禽，全长38~45厘米。成年雄鸟繁殖期绚丽多彩；非繁殖期和雌鸟类似。雌鸟羽色灰暗，眼周有明显的白色眼圈和眼线。","habitat_notes":"城区各大园林水域几乎常年可见，郊区的湖泊、溪流等湿地环境亦很容易见到。","seasonality_notes":"常年可见。","cover_image_url":"/birds/aix-galericulata.jpg","is_active":true},{"slug":"sibirionetta-formosa","common_name":"花脸鸭","scientific_name":"Sibirionetta Formosa","aliases":["巴鸭","眼镜鸭"],"taxon_group":"鸭科 花脸鸭属","identification_notes":"小型游禽，全长36~42厘米。成年雄鸟繁殖期头部花纹很具特色。雌鸟褐色斑驳，嘴基处有一块近白色的圆斑。","habitat_notes":"见于北京城郊各种类型的湿地，通常出现在较大水域。","seasonality_notes":"主要为旅鸟，也有零星冬候鸟个体。","cover_image_url":"/birds/sibirionetta-formosa.jpg","is_active":true},{"slug":"anas-platyrhynchos","common_name":"绿头鸭","scientific_name":"Anas platyrhynchos","aliases":["野鸭","大红腿儿","大青头"],"taxon_group":"鸭科 鸭属","identification_notes":"中型游禽，全长50~60厘米。成年雄鸟繁殖期头绿、颈有白环，尾具两个黑色弯钩。成年雌鸟繁殖期全身浅棕色，满布褐色斑纹，嘴边橙色、中部褐色。","habitat_notes":"从市中心的护城河、公园湖区到郊区的鱼塘、水库，几乎只要有湿地的地方都能见到。","seasonality_notes":"全年可见，可能有些是留居个体。","cover_image_url":"/birds/anas-platyrhynchos.jpg","is_active":true},{"slug":"anas-poecilorhyncha","common_name":"斑嘴鸭","scientific_name":"Anas poecilorhyncha","aliases":["黄嘴尖鸭","黑毛"],"taxon_group":"鸭科 鸭属","identification_notes":"中型游禽，全长53~63厘米。雌雄相似。嘴黑色，嘴端有一块显著黄斑。","habitat_notes":"栖息于各种湿地，和绿头鸭相似。","seasonality_notes":"全年可见，但不确定是否有留居个体。","cover_image_url":"/birds/anas-poecilorhyncha.jpg","is_active":true},{"slug":"netta-rufina","common_name":"赤嘴潜鸭","scientific_name":"Netta rufina","aliases":[],"taxon_group":"鸭科 狭嘴潜鸭属","identification_notes":"中型游禽，全长45~55厘米。成年雄鸟嘴红色、头棕黄色、后颈及前胸棕黑色、上体灰褐色。雌鸟脸、颈侧灰白色，其余大部灰褐色，嘴灰褐色、尖端黄色。","habitat_notes":"市区的一些公园（如颐和园、紫竹院等）及周边湿地。","seasonality_notes":"本是不太常见的旅鸟，近年来在局部区域内已成为比较常见的留鸟。","cover_image_url":"/birds/netta-rufina.jpg","is_active":true},{"slug":"aythya-ferina","common_name":"红头潜鸭","scientific_name":"Aythya ferina","aliases":["红头鸭"],"taxon_group":"鸭科 潜鸭属","identification_notes":"中型游禽，全长42~49厘米。成年雄鸟繁殖期头颈棕红色，虹膜红色，嘴黑色、前端有一条宽浅色区域。雌鸟头、颈褐色，眼后有浅色区域。","habitat_notes":"多见于比较开阔的水域，如京郊各大水库及市区公园的大型水面。","seasonality_notes":"主要为旅鸟，偶尔有少量越冬，9月末至次年4月可见。","cover_image_url":"/birds/aythya-ferina.jpg","is_active":true},{"slug":"aythya-fuligula","common_name":"凤头潜鸭","scientific_name":"Aythya fuligula","aliases":[],"taxon_group":"鸭科 潜鸭属","identification_notes":"中型游禽，全长40~49厘米。成年雄鸟头部黑色、闪蓝紫色金属光泽，头顶有一撮长冠羽，虹膜黄色。雌鸟灰褐色，头顶羽冠较小。","habitat_notes":"主要栖息在北京郊区有较大水域的湿地，市区公园的大型湖泊中也能见到。","seasonality_notes":"主要为旅鸟，春秋迁徙季节较为常见，冬季偶有少量个体在此越冬。","cover_image_url":"/birds/aythya-fuligula.jpg","is_active":true},{"slug":"bucephala-clangula","common_name":"鹊鸭","scientific_name":"Bucephala clangula","aliases":["喜鹊鸭子","金眼鸭"],"taxon_group":"鸭科 鹊鸭属","identification_notes":"中小型游禽，全长32~48厘米。成年雄鸟头黑色，嘴基后有一个较大的白色斑块，虹膜金黄色。雌鸟头褐色，嘴端橙黄色。","habitat_notes":"多见于郊区大型水域，有时在市区公园水面也能见到零星个体或小群。","seasonality_notes":"旅鸟、冬候鸟。","cover_image_url":"/birds/bucephala-clangula.jpg","is_active":true},{"slug":"mergellus-albellus","common_name":"斑头秋沙鸭","scientific_name":"Mergellus albellus","aliases":["熊猫鸭","白秋沙鸭"],"taxon_group":"鸭科 斑头秋沙鸭属","identification_notes":"中小型游禽，全长38~44厘米。成年雄鸟周身以白色为主，有几条黑色细条纹，脸部有一个大黑眼圈，头顶具羽冠。雌鸟头部上棕下白，上体灰色。","habitat_notes":"喜欢栖息于开阔水域，潜水觅食。","seasonality_notes":"旅鸟、冬候鸟，10月至次年4月可见。","cover_image_url":"/birds/mergellus-albellus.jpg","is_active":true},{"slug":"mergus-merganser","common_name":"普通秋沙鸭","scientific_name":"Mergus merganser","aliases":["鱼鹰","秋沙鸭"],"taxon_group":"鸭科 秋沙鸭属","identification_notes":"中型游禽，全长54~68厘米。嘴细长、尖端略带钩，身体呈长梭形。成年雄鸟繁殖期头黑、上体黑白相间，嘴暗红色。雌鸟头颈棕黄，头后有发达的丝状羽冠。","habitat_notes":"开阔水域，各大水库及公园湖区都能见到。","seasonality_notes":"旅鸟、冬候鸟，10月至次年4月中旬可见。","cover_image_url":"/birds/mergus-merganser.jpg","is_active":true},{"slug":"pandion-haliaetus","common_name":"鹗","scientific_name":"Pandion haliaetus","aliases":["鱼鹰"],"taxon_group":"鹗科 鹗属","identification_notes":"中型猛禽，全长51~65厘米。雌雄相似。上体暗褐色，下体近白色，胸部有一些褐色斑点，黑色的贯眼纹一直延伸到枕后。","habitat_notes":"多在大型湿地活动，郊区的各大水库、河流上空，颐和园、圆明园福海也会有零星个体。","seasonality_notes":"旅鸟，通常3月至5月、9月至11月可见。","cover_image_url":"/birds/pandion-haliaetus.jpg","is_active":true},{"slug":"pernis-ptilorhynchus","common_name":"凤头蜂鹰","scientific_name":"Pernis ptilorhynchus","aliases":["蜜鹰"],"taxon_group":"鹰科 蜂鹰属","identification_notes":"中型偏大的猛禽，全长55~67厘米。翅、尾宽大，但头偏小。色型复杂，有浅棕、黑白相间、棕黄、黑褐等多种类型。","habitat_notes":"多见于山区，城市上空也能见到迁徙经过的个体或小群。","seasonality_notes":"旅鸟，每年5月至6月初、8月末至10月初可见。","cover_image_url":"/birds/pernis-ptilorhynchus.jpg","is_active":true},{"slug":"milvus-migrans","common_name":"黑鸢","scientific_name":"Milvus migrans","aliases":["老鹰","黑耳鸢"],"taxon_group":"鹰科 鸢属","identification_notes":"中型猛禽，全长60~65厘米。成鸟周身棕褐色；幼鸟颜色较浅，腹部满布浅棕色纵纹。飞行时翼下有明显的大白斑，尾羽呈浅叉状。","habitat_notes":"市区上空及近郊等地。","seasonality_notes":"除1月、12月外，全年可见，春秋两季迁徙过境时常见。","cover_image_url":"/birds/milvus-migrans.jpg","is_active":true},{"slug":"haliaeetus-albicilla","common_name":"白尾海雕","scientific_name":"Haliaeetus albicilla","aliases":["黄嘴雕","白尾雕"],"taxon_group":"鹰科 海雕属","identification_notes":"大型猛禽，全长85~95厘米。成鸟黄褐色，头颈羽色较浅，尾楔形白色，嘴黄色、厚而粗壮。幼鸟羽色以褐色为主，杂以浅色斑点。","habitat_notes":"喜欢在大型水域附近活动，北京沙河水库、官厅水库、十三陵水库等。","seasonality_notes":"旅鸟、冬候鸟，10月至次年4月初可见。","cover_image_url":"/birds/haliaeetus-albicilla.jpg","is_active":true},{"slug":"aegypius-monachus","common_name":"秃鹫","scientific_name":"Aegypius monachus","aliases":["座山雕"],"taxon_group":"鹰科 秃鹫属","identification_notes":"大型猛禽，全长110厘米左右，周身黑褐色，头部为短绒毛，嘴厚重粗壮。","habitat_notes":"通常生活在北京远郊山区，如门头沟、房山、昌平等地的山区，有时也会飞到平原荒野。","seasonality_notes":"冬候鸟、留鸟(存疑)。夏季极少见，多在春秋或冬季。","cover_image_url":"/birds/aegypius-monachus.jpg","is_active":true},{"slug":"circus-cyaneus","common_name":"白尾鹞","scientific_name":"Circus cyaneus","aliases":["白尾巴根儿"],"taxon_group":"鹰科 鹞属","identification_notes":"中型猛禽，全长41~53厘米。成年雄鸟头部及上体蓝灰色，下体偏白，尾上覆羽白色。雌鸟上体褐色斑驳，尾上覆羽白色很明显。","habitat_notes":"喜欢在水田、沼泽、苇塘、河滩、荒地等开阔的湿地环境活动。","seasonality_notes":"旅鸟、冬候鸟，夏季偶尔零星可见。","cover_image_url":"/birds/circus-cyaneus.jpg","is_active":true},{"slug":"accipiter-nisus","common_name":"雀鹰","scientific_name":"Accipiter nisus","aliases":["细胸","鹞子"],"taxon_group":"鹰科 鹰属","identification_notes":"小型猛禽，全长32~43厘米。成年雄鸟上体青灰色，下体具有较淡的棕红色横纹。雌鸟上体偏褐色，下体灰褐色横纹细密，头部白色眉纹显著。","habitat_notes":"偏好林地生境，市区公园、小区里也有出现。","seasonality_notes":"全年可见，夏季在山区林地繁殖，春秋有大量过境，冬季有越冬。","cover_image_url":"/birds/accipiter-nisus.jpg","is_active":true},{"slug":"buteo-buteo","common_name":"普通𫛭","scientific_name":"Buteo buteo","aliases":["粑粑鹰"],"taxon_group":"鹰科 𫛭属","identification_notes":"中型猛禽，全长50~56厘米。外形敦实，胸腹部多有一条很宽的深色横带区域，飞行时翼下有比较明显的腕斑，尾形较圆。","habitat_notes":"市区、郊区农田等开阔区域。","seasonality_notes":"除夏季（6月至8月）外，其余时段均可见，春秋迁徙季常见。","cover_image_url":"/birds/buteo-buteo.jpg","is_active":true},{"slug":"aquila-chrysaetos","common_name":"金雕","scientific_name":"Aquila chrysaetos","aliases":["红头雕","洁白雕"],"taxon_group":"鹰科 雕属","identification_notes":"大型猛禽，全长78~105厘米。全身深褐色，头顶、枕部至后颈的羽毛为金黄色。幼鸟翅展开后有明显的大白斑，尾羽具白色宽带。","habitat_notes":"大多数都在远郊山区活动。","seasonality_notes":"留鸟，全年可见。","cover_image_url":"/birds/aquila-chrysaetos.jpg","is_active":true},{"slug":"falco-tinnunculus","common_name":"红隼","scientific_name":"Falco tinnunculus","aliases":["茶隼","山巴虎子","山涧子"],"taxon_group":"隼科 隼属","identification_notes":"小型猛禽，全长31~38厘米。成年雄鸟头蓝灰色；上体砖褐色；尾蓝灰色；下体土黄色。雌鸟头、尾和上体颜色一致，都为砖红色。头部脸侧都有很明显的深色髭纹。","habitat_notes":"适应性很强，在城市里生活得也不错。","seasonality_notes":"全年可见，夏候鸟、旅鸟、冬候鸟都有。","cover_image_url":"/birds/falco-tinnunculus.jpg","is_active":true},{"slug":"falco-amurensis","common_name":"红脚隼","scientific_name":"Falco amurensis","aliases":["蚂蚱鹰","阿穆尔隼"],"taxon_group":"隼科 隼属","identification_notes":"小型猛禽，全长26~30厘米。成年雄鸟上体深蓝灰色，下体浅灰色，尾下覆羽栗红色。雌鸟上体暗灰色，眼周、蜡膜及足都为橙色。","habitat_notes":"通常在农田、荒地或林缘等开阔地的上空活动。","seasonality_notes":"旅鸟、夏候鸟，4月至10月可见。","cover_image_url":"/birds/falco-amurensis.jpg","is_active":true},{"slug":"falco-subbuteo","common_name":"燕隼","scientific_name":"Falco subbuteo","aliases":["青条子","熊猫垛子"],"taxon_group":"隼科 隼属","identification_notes":"小型猛禽，全长29~33厘米。头部黑褐色区域向下延伸出两块突起，有细白色眉纹；下体白色，具深色纵纹；下腹及尾下覆羽棕红色。","habitat_notes":"栖息生境多样，湿地、农田、林地、市区园林街道等处都能见到。","seasonality_notes":"旅鸟、夏候鸟，每年4月至10月可见。","cover_image_url":"/birds/falco-subbuteo.jpg","is_active":true},{"slug":"falco-peregrinus","common_name":"游隼","scientific_name":"Falco peregrinus","aliases":["鸭虎","鸽鹰"],"taxon_group":"隼科 隼属","identification_notes":"中型猛禽，全长40~50厘米。成年头灰黑色，背部青灰色，下体白色，缀有黑褐色横斑。飞行时翅尖尾短，身体粗壮。","habitat_notes":"市区上空有时出现，也会在湿地或开阔山谷。","seasonality_notes":"全年可见，以春秋迁徙季较多。","cover_image_url":"/birds/falco-peregrinus.jpg","is_active":true},{"slug":"coturnix-japonica","common_name":"鹌鹑","scientific_name":"Coturnix japonica","aliases":[],"taxon_group":"雉科 鹌鹑属","identification_notes":"小型陆禽，全长15~20厘米，整体球形。上体棕黄色，下体浅土黄色。颈部、肩背、两胁都有浅黄色尖细条纹。","habitat_notes":"主要在平原、低山地区的农田、草丛环境活动。市区公园、小区的灌丛草地也会有。","seasonality_notes":"全年可见，春秋迁徙季较为常见。","cover_image_url":"/birds/coturnix-japonica.jpg","is_active":true},{"slug":"crossoptilon-mantchuricum","common_name":"褐马鸡","scientific_name":"Crossoptilon mantchuricum","aliases":["鹖"],"taxon_group":"雉科 马鸡属","identification_notes":"大型陆禽。全长85~100厘米，周身褐色，尾羽白色、丝状下垂，眼周有红色裸区，脸侧有白色羽毛，头后形成耳羽簇。","habitat_notes":"在北京分布十分有限，只见于西部门头沟山区。","seasonality_notes":"全年可见。","cover_image_url":"/birds/crossoptilon-mantchuricum.jpg","is_active":true},{"slug":"phasianus-colchicus","common_name":"环颈雉","scientific_name":"Phasianus colchicus","aliases":["野鸡","山鸡","雉鸡"],"taxon_group":"雉科 雉属","identification_notes":"中大型陆禽。雄鸟羽色艳丽，具超长尾羽，颈部有一个白环。雌鸟尾相对较短，周身斑驳。","habitat_notes":"分布于北京山区及附近的林地、农田中。","seasonality_notes":"留鸟。","cover_image_url":"/birds/phasianus-colchicus.jpg","is_active":true},{"slug":"grus-grus","common_name":"灰鹤","scientific_name":"Grus grus","aliases":["灰鹚"],"taxon_group":"鹤科 鹤属","identification_notes":"大型涉禽，全长100~130厘米。成鸟全身大部分灰色，头顶皮肤裸区鲜红色，前颈黑色，眼后至后颈灰白色，飞羽端部黑色。","habitat_notes":"主要见于野鸭湖、密云水库等远郊湿地及附近农田。","seasonality_notes":"每年10月中旬至次年4月初可见。","cover_image_url":"/birds/grus-grus.jpg","is_active":true},{"slug":"gallinula-chloropus","common_name":"黑水鸡","scientific_name":"Gallinula chloropus","aliases":["红骨顶","水鸡"],"taxon_group":"秧鸡科 黑水鸡属","identification_notes":"中型涉禽，全长30~35厘米。成鸟周身黑色，嘴（包括额甲）鲜红色，嘴尖端黄色。幼鸟整体偏褐色，无明显额甲。","habitat_notes":"几乎只要挺水植物比较丰富的水域都能见到。夏季市中心公园荷塘也时常有。","seasonality_notes":"全年可见。","cover_image_url":"/birds/gallinula-chloropus.jpg","is_active":true},{"slug":"fulica-atra","common_name":"白骨顶","scientific_name":"Fulica atra","aliases":["骨顶鸡"],"taxon_group":"秧鸡科 骨顶属","identification_notes":"中型涉禽，全长36~43厘米。成鸟全身黑色，嘴及额甲白色。","habitat_notes":"主要在郊区一些植被丰富的湿地繁殖，市区公园湿地中也能见到。","seasonality_notes":"全年可见。","cover_image_url":"/birds/fulica-atra.jpg","is_active":true},{"slug":"otis-tarda","common_name":"大鸨","scientific_name":"Otis tarda","aliases":["地"],"taxon_group":"鸨科 鸨属","identification_notes":"大型陆禽，全长1米左右。上体棕色、满布黑褐色波浪纹，下体灰白色。雄鸟繁殖期脸侧有“白胡子”。","habitat_notes":"通常分布在北京远郊的农田、河滩荒地。","seasonality_notes":"旅鸟、冬候鸟，10月至次年4月可见。","cover_image_url":"/birds/otis-tarda.jpg","is_active":true},{"slug":"himantopus-himantopus","common_name":"黑翅长脚鹬","scientific_name":"Himantopus himantopus","aliases":["高跷鹬","红娘"],"taxon_group":"反嘴鹬科 长脚鹬属","identification_notes":"中小型涉禽，全长30~40厘米。成鸟羽色黑白搭配，腿脚红色、超长。","habitat_notes":"喜欢栖息于有浅滩的湿地。","seasonality_notes":"旅鸟、夏候鸟，410月可见。","cover_image_url":"/birds/himantopus-himantopus.jpg","is_active":true},{"slug":"vanellus-vanellus","common_name":"凤头麦鸡","scientific_name":"Vanellus vanellus","aliases":[],"taxon_group":"鸻科 麦鸡属","identification_notes":"中型涉禽，全长29~34厘米。成年雄鸟上体黑褐色，具金属光泽，头顶有明显的黑色长凤头。雌鸟凤头较短。","habitat_notes":"多见于郊区的开阔湿地、农田。","seasonality_notes":"旅鸟、夏候鸟，3月至11月可见。","cover_image_url":"/birds/vanellus-vanellus.jpg","is_active":true},{"slug":"charadrius-dubius","common_name":"金眶鸻","scientific_name":"Charadrius dubius","aliases":["金眼圈"],"taxon_group":"鸻科 鸻属","identification_notes":"小型涉禽，全长15~18厘米。成鸟繁殖期头部具黑色“眼罩”；颈部有黑色围领；眼周一圈金黄色十分突出。","habitat_notes":"喜欢开阔的湿地滩涂，人工湿地鹅卵石滩等处也偶有出现。","seasonality_notes":"夏候鸟、旅鸟，3月至11月可见。","cover_image_url":"/birds/charadrius-dubius.jpg","is_active":true},{"slug":"gallinago-gallinago","common_name":"扇尾沙锥","scientific_name":"Gallinago gallinago","aliases":["水扎"],"taxon_group":"鹬科 沙锥属","identification_notes":"小型涉禽，全长25~29厘米。体羽满布深棕及黑色斑纹。嘴突出，长度约为头长2倍。","habitat_notes":"常见于非硬化水底的湿地生境，如农田沟渠、水库滩涂、公园浅滩等。","seasonality_notes":"每年春秋两季（3月至5月，8月中旬至10月）可见。","cover_image_url":"/birds/gallinago-gallinago.jpg","is_active":true},{"slug":"chroicocephalus-ridibundus","common_name":"红嘴鸥","scientific_name":"Chroicocephalus ridibundus","aliases":["黑头鸥","笑鸥","钓鱼郎"],"taxon_group":"鸥科 彩头鸥属","identification_notes":"中型游禽，全长35~43厘米。成鸟繁殖期头部暗褐，具较窄白色眼圈；嘴暗红。非繁殖期头部白，眼前和耳区黑灰。","habitat_notes":"城郊各种类型的湿地都能见到。","seasonality_notes":"旅鸟，春秋迁徙季节多见。","cover_image_url":"/birds/chroicocephalus-ridibundus.jpg","is_active":true},{"slug":"chlidonias-hybrida","common_name":"灰翅浮鸥","scientific_name":"Chlidonias hybrida","aliases":[],"taxon_group":"鸥科 浮鸥属","identification_notes":"小型游禽，全长23~29厘米。成鸟繁殖期头的上半部黑色，脸侧白色；上体青灰色，下体暗灰色。非繁殖期头部黑色减退。","habitat_notes":"常见于各种类型的湿地生境。","seasonality_notes":"旅鸟、夏候鸟。5月至10月可见。","cover_image_url":"/birds/chlidonias-hybrida.jpg","is_active":true},{"slug":"streptopelia-orientalis","common_name":"山斑鸠","scientific_name":"Streptopelia orientalis","aliases":["斑鸠"],"taxon_group":"鸠鸽科 斑鸠属","identification_notes":"中型陆禽，全长30~35厘米。身体较为粗壮，后颈部具浅蓝色、黑色相间的条纹；肩羽和翅上有大鱼鳞纹图案。","habitat_notes":"多生活在山区及近山区的林地、林缘环境，也会到附近农田活动。","seasonality_notes":"留鸟。","cover_image_url":"/birds/streptopelia-orientalis.jpg","is_active":true},{"slug":"streptopelia-chinensis","common_name":"珠颈斑鸠","scientific_name":"Streptopelia chinensis","aliases":["野鸽子","斑鸠"],"taxon_group":"鸠鸽科 斑鸠属","identification_notes":"中型陆禽，全长27~33厘米。颈、胸部粉灰色，颈部有一条黑底带白珍珠点的“围巾”。","habitat_notes":"多在平原及低山区活动，小区、公园、路边绿地都能见到。","seasonality_notes":"留居北京，全年可见。","cover_image_url":"/birds/streptopelia-chinensis.jpg","is_active":true},{"slug":"cuculus-micropterus","common_name":"四声杜鹃","scientific_name":"Cuculus micropterus","aliases":["光棍好苦"],"taxon_group":"杜鹃科 杜鹃属","identification_notes":"中型攀禽，全长30~34厘米。整体羽色较深，尾端部黑宽带明显，虹膜褐色。","habitat_notes":"主要生活在山区及平原的林地环境，在市区树木繁茂的公园、小区也较常见。","seasonality_notes":"夏候鸟、旅鸟，5月至9月可见。","cover_image_url":"/birds/cuculus-micropterus.jpg","is_active":true},{"slug":"cuculus-canorus","common_name":"大杜鹃","scientific_name":"Cuculus canorus","aliases":["布谷鸟"],"taxon_group":"杜鹃科 杜鹃属","identification_notes":"中型攀禽，体长28~34厘米。成鸟雄鸟上体青灰色，腹部白色且具深色细横纹。眼睛虹膜黄色。幼鸟上体褐色。","habitat_notes":"主要见于湿地环境附近。","seasonality_notes":"夏候鸟、旅鸟，每年5月至9月可见。","cover_image_url":"/birds/cuculus-canorus.jpg","is_active":true},{"slug":"otus-sunia","common_name":"红角鸮","scientific_name":"Otus sunia","aliases":["东方角鸮"],"taxon_group":"鸱鸮科 角鸮属","identification_notes":"小型猛禽，全长17~20厘米。非常袖珍。周身密布驳杂的斑纹，头部有两个羽簇，眼睛虹膜黄色。","habitat_notes":"主要生活在林地生境，市区一些乔木丰富的园林、小区也有。","seasonality_notes":"夏候鸟、旅鸟，4月至10月可见。","cover_image_url":"/birds/otus-sunia.jpg","is_active":true}]$json$::jsonb) AS item(
    slug TEXT,
    common_name TEXT,
    scientific_name TEXT,
    aliases TEXT[],
    taxon_group TEXT,
    identification_notes TEXT,
    habitat_notes TEXT,
    seasonality_notes TEXT,
    cover_image_url TEXT,
    is_active BOOLEAN
  )
),
sanitized_source AS (
  SELECT
    slug,
    common_name,
    scientific_name,
    COALESCE(aliases, ARRAY[]::TEXT[]) AS aliases,
    taxon_group,
    identification_notes,
    habitat_notes,
    seasonality_notes,
    CASE
      WHEN cover_image_url LIKE '/birds/%' THEN NULL
      ELSE NULLIF(cover_image_url, '')
    END AS cover_image_url,
    COALESCE(is_active, TRUE) AS is_active
  FROM source
),
updated_species AS (
  UPDATE public.species AS target
     SET common_name = src.common_name,
         scientific_name = src.scientific_name,
         aliases = src.aliases,
         taxon_group = src.taxon_group,
         identification_notes = src.identification_notes,
         habitat_notes = src.habitat_notes,
         seasonality_notes = src.seasonality_notes,
         cover_image_url = COALESCE(target.cover_image_url, src.cover_image_url),
         is_active = src.is_active,
         updated_at = now()
    FROM sanitized_source AS src
   WHERE target.scientific_name = src.scientific_name
      OR target.slug = src.slug
  RETURNING target.id
)
INSERT INTO public.species (
  slug,
  common_name,
  scientific_name,
  aliases,
  taxon_group,
  identification_notes,
  habitat_notes,
  seasonality_notes,
  cover_image_url,
  is_active
)
SELECT
  src.slug,
  src.common_name,
  src.scientific_name,
  src.aliases,
  src.taxon_group,
  src.identification_notes,
  src.habitat_notes,
  src.seasonality_notes,
  src.cover_image_url,
  src.is_active
FROM sanitized_source AS src
WHERE NOT EXISTS (
  SELECT 1
  FROM public.species AS target
  WHERE target.scientific_name = src.scientific_name
     OR target.slug = src.slug
);
